      // sampled endpoints. Its rectangle is conservative inside the edit mask.
      const angle=b.tiltDeg*Math.PI/180;
      for(const p of b.glyph){const x=p.x-b.center.x,y=p.y-b.center.y,angles=[-angle,angle];
